/* Period selection only: uses the existing native Vimshottari timeline. */
(()=>{'use strict';const $=id=>document.getElementById(id);let mode='current',choices=[0,0,0],roots=[],chain=[],signature='';
const code=p=>window.KPDisplay.idByName[p.lord]||p.id,esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function resolve(){KPHomeDasha.refresh();const data=KPHomeDasha.getData();if(!data?.ready)throw Error('Calculate the kundali to see its current DBA.');roots=data.levels[0].rows;const key=JSON.stringify([$('dob')?.value,$('birthTime')?.value,roots.map(p=>[p.key,p.startMs,p.endMs])]);if(key!==signature){signature=key;mode='current';}const civil=Date.now()+Number(data.timeZoneHours)*3600000;let rows=roots,low=-Infinity,high=Infinity;chain=[];for(let i=0;i<3;i++){if(mode==='current'){choices[i]=rows.findIndex(p=>p.startMs<=civil&&civil<p.endMs);if(choices[i]<0)throw Error('The current date is outside the native DBA timeline. Check the birth details.');}if(!rows[choices[i]])choices[i]=0;const row=rows[choices[i]];if(!row)throw Error('The selected DBA period is unavailable.');const select=$('hq-dba-'+['md','ad','pd'][i]);if(select){select.replaceChildren(...rows.map((p,n)=>new Option(code(p)+' · '+p.start.slice(0,10)+' → '+p.end.slice(0,10),String(n))));select.value=String(choices[i]);}low=Math.max(low,row.startMs);high=Math.min(high,row.endMs);chain.push({...row,level:['MD','AD','PD'][i],id:code(row),startMs:low,endMs:high,start:new Date(low).toISOString().slice(0,19),end:new Date(high).toISOString().slice(0,19)});rows=KPHomeDasha.subdivide(row);}return chain;}
function periods(){return resolve().map(p=>({level:p.level,id:p.id,start:p.start,end:p.end}));}
function render(data){const body=$('hq-dba-rows'),status=$('hq-dba-status');if(!body)return;if(!data?.ready){body.innerHTML='';status.textContent=data?.reason||'Calculate the kundali first.';return;}status.textContent=(mode==='current'?'Current DBA · ':'Selected DBA · ')+data.periods.map(p=>p.level+' '+p.id).join(' / ');body.innerHTML=data.periodChecks.map(r=>'<tr><th>'+esc(r.level)+' · '+esc(r.id)+'</th><td>'+esc(r.houses.join(', ')||'—')+'<small>'+esc(r.start.replace('T',' ')+' → '+r.end.replace('T',' '))+'</small></td><td>'+esc(window.KPPreferences?.get().language==='marathi'?(r.verdict.promised?'घटनेचे वचन आहे':'घटनेचे वचन नाही'):(r.verdict.promised?'Event is promised':'Event is not promised'))+'</td></tr>').join('');$('hq-dba-note').textContent='All MD / AD / PD checked using '+(data.method==='sixfold'?'six-fold':'four-fold')+' significators. '+(data.periodChecks.every(r=>r.verdict.promised)?'All three support a required house alternative.':'One or more periods do not cover a complete required house alternative.')+' Additional event conditions and transits still apply.';}
function current(){mode='current';return window.KPHoraryResults.refresh();}
function init(){const panel=$('hq-panel');if(!panel||$('hq-dba-panel'))return;const wrap=document.createElement('div');wrap.id='hq-workspace';panel.before(wrap);wrap.append(panel);const aside=document.createElement('aside');aside.id='hq-dba-panel';aside.className='card';aside.innerHTML='<header><h2>DBA · Event Promise</h2><button type="button" id="hq-dba-current">Current DBA</button></header><div class="hq-dba-selectors">'+['md','ad','pd'].map((k,i)=>'<label>'+['Dasha · MD','Bhukti · AD','Antara · PD'][i]+'<select id="hq-dba-'+k+'"></select></label>').join('')+'</div><p id="hq-dba-status" role="status"></p><div class="hq-dba-table"><table><thead><tr><th>Period</th><th>Signified houses / period</th><th>Event house support</th></tr></thead><tbody id="hq-dba-rows"></tbody></table></div><p id="hq-dba-note"></p>';wrap.append(aside);$('hq-dba-current').onclick=current;aside.addEventListener('change',e=>{const index=['hq-dba-md','hq-dba-ad','hq-dba-pd'].indexOf(e.target.id);if(index<0)return;mode='selected';choices[index]=Number(e.target.value);for(let i=index+1;i<3;i++)choices[i]=0;KPHoraryResults.refresh();});const section=$('horary-results');let active=section.classList.contains('active');new MutationObserver(()=>{const next=section.classList.contains('active');if(next&&!active)current();active=next;}).observe(section,{attributes:true,attributeFilter:['class']});current();}
window.KPHoraryDBA=Object.freeze({periods,render,current,mode:()=>mode});function start(){if($('hq-panel'))init();else{const observer=new MutationObserver(()=>{if($('hq-panel')){observer.disconnect();init();}});observer.observe(document,{childList:true,subtree:true});}}if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',start);else start();})();
